import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./HomeStyle.css";

import donation from "../../assets/images/Online-Donation.jpg";
import safeers from "../../assets/images/Safeers.jpg";
import banks from "../../assets/images/bank.jpg";
import arabicMonthly from "../../assets/images/arabicMonthly.jpg";
import arabicQuarterly from "../../assets/images/arabicQuarterly.jpg";
import news from "../../assets/images/news.jpg";
import admission from "../../assets/images/admission.jpg";
import urdu from "../../assets/images/urdu.png";
import english from "../../assets/images/english.png";
import arabic from "../../assets/images/arabic.png";
import hindi from "../../assets/images/hindi.png";
import gujarati from "../../assets/images/gujarati.png";

const defaultIntroductions = {
  arabic: { visible: true },
  urdu: { visible: true },
  english: { visible: false },
  hindi: { visible: true },
  gujarati: { visible: true },
};

const allLanguages = [
  { name: "Arabic", code: "arabic", image: arabic },
  { name: "Urdu", code: "urdu", image: urdu },
  { name: "English", code: "english", image: english },
  { name: "Hindi", code: "hindi", image: hindi },
  { name: "Gujarati", code: "gujarati", image: gujarati },
];

const magazineData = [{
    "month": "2026-06",
    "name": "મકસદે મુસ્તફા ﷺ",
    "serialNumber": "1",
    "thumbnail": "data:image/jpeg;base64,",
    "pdf": "data:application/pdf;base64,",
    "id": 1781796150849
},{
    "month": "2026-07",
    "name": "મકસદે મુસ્તફા ﷺ",
    "serialNumber": "2",
    "thumbnail": "data:image/jpeg;base64,",
    "pdf": "data:application/pdf;base64,",
    "id": 1781796150849
}]

export default function Home() {
  const navigate = useNavigate();

  const [visibleLanguages, setVisibleLanguages] = useState(() =>
    allLanguages.filter((lang) => defaultIntroductions[lang.code]?.visible !== false)
  );

  const notices = [news, admission];
  const magazines = [arabicMonthly];

  useEffect(() => {
    const savedIntroductions = localStorage.getItem('introductions');
    if (savedIntroductions) {
      try {
        const parsed = JSON.parse(savedIntroductions);
        const mergedIntroductions = { ...defaultIntroductions, ...parsed };
        setVisibleLanguages(
          allLanguages.filter((lang) => mergedIntroductions[lang.code]?.visible !== false)
        );
      } catch (error) {
        console.error('Failed to parse introductions from localStorage', error);
      }
    }
  }, []);

  const galleryImages = [
    {
      image: donation,
      title: "Online Donation",
      link: "/donation",
    },
    {
      image: banks,
      title: "Bank Details",
      link: "/bank-details",
    },
    {
      image: safeers,
      title: "Safeers",
      link: "/gallery",
    },
  ];

  return (
    <section className="home-section">
      <div className="home-heading">
        <h1>Welcome to Darool Uloom Hidayatul Islam</h1>
        <p>Traditional Islamic Education with Modern Values</p>
      </div>

      <div className="home-grid">
        {/* Column 1 */}
        <div className="home-card">
          <div className="language-grid">
            {visibleLanguages.map((lang, index) => (
              <div className="language-card" key={index}>
                <img src={lang.image} alt={lang.name} />
                <button
                  className="language-button"
                  onClick={() => navigate(`/introduction/${lang.code}`)}
                >
                  {lang.name} Introduction
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Column 2 */}
        <div className="home-card">
          <div className="image-grid">
            {notices.map((img, index) => (
              <img src={img} alt="notice" key={index} />
            ))}
          </div>
        </div>

        {/* Column 3 */}
        <div className="home-card">
          <div className="image-grid">
            {magazineData.map((img, index) => (
              <div>
              <img src={img?.thumbnail} alt="magazine" key={index} />
              <h3>serial Number {img?.serialNumber}</h3>
            </div>
            ))}
          </div>
        </div>

        {/* Column 4 */}
        <div className="home-card">
          <div className="image-grid">
            {galleryImages.map((item, index) => (
              <img
                key={index}
                src={item.image}
                alt={item.title}
                title={item.title}
                onClick={() => navigate(item.link)}
                style={{ cursor: "pointer" }}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}